script:
// SEPA Lastschrift Dashboard
frappe.call({
	method: 'hibiscus_connect.hibiscus_connect.doctype.hibiscus_connect_sepa_lastschrift_funktionen.hibiscus_connect_sepa_lastschrift_funktionen.get_dashboard_data',
	callback: function(r) {
		const $loading = root_element.querySelector('.sepa-dashboard-loading');
		const $content = root_element.querySelector('.sepa-dashboard-content');

		if (r.message) {
			const data = r.message;
			const hasOverdue = data.count_faellig > 0;
			const statusClass = hasOverdue ? 'red' : 'green';
			const statusIcon = hasOverdue ? 'alert-circle' : 'check';
			const statusText = hasOverdue ? 'Faellige Lastschriften vorhanden!' : 'Keine faelligen Lastschriften';
			const lastCheck = data.last_check ? frappe.datetime.str_to_user(data.last_check) : 'Noch nie';

			let html = `
				<div style="display: flex; gap: 20px; flex-wrap: wrap;">
					<div class="dashboard-card" style="flex: 1; min-width: 280px; padding: 20px; border-radius: 8px; background: var(--card-bg); border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);">
						<div style="display: flex; align-items: center; gap: 10px; margin-bottom: 15px;">
							<span class="indicator-pill ${statusClass}" style="padding: 4px 8px;">
								<svg class="icon icon-sm"><use href="#icon-${statusIcon}"></use></svg>
							</span>
							<span style="font-weight: 600; font-size: 14px;">${statusText}</span>
						</div>
						${hasOverdue ? `
							<div style="display: flex; gap: 40px; margin-top: 15px;">
								<div>
									<div class="text-muted" style="font-size: 11px; text-transform: uppercase;">Anzahl</div>
									<div style="font-size: 28px; font-weight: 700; color: var(--text-color);">${data.count_faellig}</div>
								</div>
								<div>
									<div class="text-muted" style="font-size: 11px; text-transform: uppercase;">Summe</div>
									<div style="font-size: 28px; font-weight: 700; color: var(--text-color);">${data.total_faellig_formatted}</div>
								</div>
							</div>
						` : ''}
						<div style="margin-top: 20px; padding-top: 15px; border-top: 1px solid var(--border-color);">
							<div style="display: flex; justify-content: space-between; align-items: center;">
								<span class="text-muted" style="font-size: 12px;">Letzter Abruf: ${lastCheck}</span>
								<a href="/app/hibiscus-connect-sepa-lastschrift-funktionen" class="btn btn-sm btn-default">Details</a>
							</div>
						</div>
					</div>
					<div class="dashboard-card" style="flex: 1; min-width: 200px; padding: 20px; border-radius: 8px; background: var(--card-bg); border: 1px solid var(--border-color); box-shadow: var(--shadow-sm);">
						<div class="text-muted" style="font-size: 11px; text-transform: uppercase; margin-bottom: 8px;">Offene Lastschriften gesamt</div>
						<div style="font-size: 28px; font-weight: 700; color: var(--text-color);">${data.count_offen}</div>
						<div style="font-size: 16px; color: var(--text-muted); margin-top: 8px;">${data.total_offen}</div>
					</div>
				</div>
			`;

			$content.innerHTML = html;
			$loading.style.display = 'none';
			$content.style.display = 'block';
		} else {
			$loading.innerHTML = '<span class="text-muted">Keine Daten verfuegbar</span>';
		}
	},
	error: function() {
		const $loading = root_element.querySelector('.sepa-dashboard-loading');
		$loading.innerHTML = '<span class="text-danger">Fehler beim Laden der Daten</span>';
	}
});
